{"path": "rest_api.py", "content": "import json


class RestAPI:
    def __init__(self, database=None):
        self.users = {}
        for user in (database or {}).get("users", []):
            self.users[user["name"]] = {
                "name": user["name"],
                "owes": dict(user.get("owes", {})),
                "owed_by": dict(user.get("owed_by", {})),
            }

    def _view(self, name):
        user = self.users[name]
        balance = sum(user["owed_by"].values()) - sum(user["owes"].values())
        return {
            "name": name,
            "owes": dict(user["owes"]),
            "owed_by": dict(user["owed_by"]),
            "balance": balance,
        }

    def get(self, url, payload=None):
        if url != "/users":
            raise ValueError("unknown url")
        names = sorted(self.users)
        if payload:
            wanted = json.loads(payload).get("users")
            if wanted is not None:
                names = sorted(n for n in wanted if n in self.users)
        return json.dumps({"users": [self._view(n) for n in names]})

    def post(self, url, payload=None):
        data = json.loads(payload) if payload else {}
        if url == "/add":
            name = data["user"]
            if name not in self.users:
                self.users[name] = {"name": name, "owes": {}, "owed_by": {}}
            return json.dumps(self._view(name))
        if url == "/iou":
            lender, borrower = data["lender"], data["borrower"]
            amount = data["amount"]
            lend, borr = self.users[lender], self.users[borrower]
            # Net against existing debt lender owes borrower.
            net = lend["owes"].pop(borrower, 0) - amount
            borr["owed_by"].pop(lender, None)
            lend["owed_by"].pop(borrower, None)
            borr["owes"].pop(lender, None)
            if net > 0:
                lend["owes"][borrower] = net
                borr["owed_by"][lender] = net
            elif net < 0:
                lend["owed_by"][borrower] = -net
                borr["owes"][lender] = -net
            names = sorted({lender, borrower})
            return json.dumps({"users": [self._view(n) for n in names]})
        raise ValueError("unknown url")
"}
